python - <<'PY'
import urllib.request, urllib.parse, json
qs=['hyperbolic generative recommendation semantic IDs','hyperbolic geometry sequential recommendation next item','generative recommendation semantic IDs behavior']
for q in qs:
 u='https://api.openalex.org/works?search='+urllib.parse.quote(q)+'&per-page=15'
 try:
  data=json.load(urllib.request.urlopen(u,timeout=20))
  print('\nQUERY',q)
  for x in data['results']:
   print(x.get('publication_year'),x.get('doi'),x['title'], 'OA', x.get('open_access',{}).get('oa_url'))
 except Exception as e: print('ERR',e)
PY

